  const emitter = new PythonEmitter(options);
  return emitter.emit(irModule);
}

module.exports = {
  PythonEmitter,
  emitPythonFromIR,
};

/**
 * V Emitter - C-Family Language
 * Converts canonical IR to v code
 */

const { BaseEmitter } = require('./base_emitter');

class VEmitter extends BaseEmitter {
    constructor() {
        super();
        this.setIndentSize(4);
        this.lineEnding = '
';
    }

    emitProgram(node) {
        if (!node.body) return '';
        return node.body.map(stmt => this.emitStatement(stmt)).join(this.lineEnding);
    }

    emitVariableDeclaration(node) {
        const declarations = node.declarations.map(decl => {
            const id = decl.id.name;
            const init = decl.init ? ' = ' + this.emitExpression(decl.init) : '';
            return id + init;
        }).join(', ');
        return this.emitLine(`var ${declarations};`);
    }

    emitFunctionDeclaration(node) {
        const name = node.id.name;
        const params = node.params.map(p => p.name).join(', ');
        const body = this.emitBlockStatement(node.body);
        return this.emitLine(`function ${name}(${params}) ${body}`);
    }

    emitClassDeclaration(node) {
        const name = node.id.name;
        const superClass = node.superClass ? ` extends ${node.superClass.name}` : '';
        const body = this.emitBlockStatement(node.body);
        return this.emitLine(`class ${name}${superClass} ${body}`);
    }

    emitIfStatement(node) {
        const test = this.emitExpression(node.test);
        const consequent = this.emitStatement(node.consequent);
        let result = this.emitLine(`if (${test}) ${consequent}`);
        if (node.alternate) {
            const alternate = this.emitStatement(node.alternate);
            result += this.emitLine(`else ${alternate}`);
        }
        return result;
    }

    emitWhileStatement(node) {
        const test = this.emitExpression(node.test);
        const body = this.emitStatement(node.body);
        return this.emitLine(`while (${test}) ${body}`);
    }

    emitForStatement(node) {
        const init = this.emitExpression(node.init);
        const test = this.emitExpression(node.test);
        const update = this.emitExpression(node.update);
        const body = this.emitStatement(node.body);
        return this.emitLine(`for (${init}; ${test}; ${update}) ${body}`);
    }

    emitForOfStatement(node) {
        const left = this.emitExpression(node.left);
        const right = this.emitExpression(node.right);
        const body = this.emitStatement(node.body);
        return this.emitLine(`for (${left} of ${right}) ${body}`);
    }

    emitBlockStatement(node) {
        let result = '{\n';
        this.increaseIndent();
        for (const stmt of node.body) {
            result += this.emitStatement(stmt) + '\n';
        }
        this.decreaseIndent();
        result += this.getIndent() + '}';
        return result;
    }

    emitReturnStatement(node) {
        const arg = node.argument ? ' ' + this.emitExpression(node.argument) : '';
        return this.emitLine(`return${arg};`);
    }

    emitExpressionStatement(node) {
        return this.emitLine(this.emitExpression(node.expression) + ';');
    }

    emitThrowStatement(node) {
        const arg = this.emitExpression(node.argument);
        return this.emitLine(`throw ${arg};`);
    }

    emitTryStatement(node) {
        let result = this.emitLine(`try ${this.emitBlockStatement(node.block)}`);
        if (node.handler) {
            const param = node.handler.param ? node.handler.param.name : 'e';
            result += this.emitLine(`catch (${param}) ${this.emitBlockStatement(node.handler.body)}`);
        }
        if (node.finalizer) {
            result += this.emitLine(`finally ${this.emitBlockStatement(node.finalizer)}`);
        }
        return result;
    }

    emitBreakStatement() {
        return this.emitLine('break;');
    }

    emitContinueStatement() {
        return this.emitLine('continue;');
    }
}

module.exports = { VEmitter };

/**
 * LUASCRIPT Enhanced Lowerer
 * 
 * Converts JavaScript AST to IR with semantic understanding.
 * Handles: async/await, classes, destructuring, control flow, templates, spread/rest
 */

const { builder } = require("./builder");
const nodes = require("./nodes");
const { IRBuilder } = require("./builder");

class EnhancedLowerer {
  constructor(irBuilder = null) {
    this.builder = irBuilder || new IRBuilder();
    this.scopeStack = [{ bindings: new Set(), parent: null }];
    this.tempVarCounter = 0;
  }

  resetState() {
    this.scopeStack = [{ bindings: new Set(), parent: null }];
    this.tempVarCounter = 0;

    if (!this.builder || typeof this.builder._storeNode !== "function") {
      this.builder = new IRBuilder();
      return;
    }

    // Clear any retained IR state when reusing an injected builder
    this.builder.nodes = {};
    this.builder.module = {
      body: [],
      metadata: this.builder.module?.metadata || {},
      source: this.builder.module?.source || {},
      directives: this.builder.module?.directives || [],
      toolchain: this.builder.module?.toolchain || {},
      schemaVersion: this.builder.module?.schemaVersion || "1.0.0",
    };
  }

  // ========== Scope Management ==========
  pushScope() {
    this.scopeStack.push({ bindings: new Set(), parent: this.scopeStack[this.scopeStack.length - 1] });
  }

  popScope() {
    this.scopeStack.pop();
  }

  getCurrentScope() {
    return this.scopeStack[this.scopeStack.length - 1];
  }

  addBinding(name) {
    this.getCurrentScope().bindings.add(name);
  }

  hasBinding(name) {
    let scope = this.getCurrentScope();
    while (scope) {
      if (scope.bindings.has(name)) return true;
      scope = scope.parent;
    }
    return false;
  }

  createTempVar(prefix = "__tmp") {
    return `${prefix}_${++this.tempVarCounter}`;
  }

  // ========== Main Lowering Entry ==========
  lower(ast) {
    this.resetState();
    return this.lowerProgram(ast);
  }

  lowerProgram(node) {
    const body = (node.body || []).map(stmt => this.lowerStatement(stmt));
    return this.builder.program(body);
  }

  // ========== Statement Lowering ==========
  // eslint-disable-next-line complexity
  lowerStatement(node) {
    if (!node) return null;

    switch (node.type) {
    case "VariableDeclaration":
      return this.lowerVariableDeclaration(node);
    case "FunctionDeclaration":
      // Check if it's a generator function
      if (node.generator) {
        return this.lowerGeneratorDeclaration(node);
      }
      return this.lowerFunctionDeclaration(node);
    case "AsyncFunctionDeclaration":
      return this.lowerAsyncFunctionDeclaration(node);
    case "ClassDeclaration":
      return this.lowerClassDeclaration(node);
    case "BlockStatement":
      return this.lowerBlockStatement(node);
    case "ExpressionStatement":
      return this.lowerExpressionStatement(node);
    case "ReturnStatement":
      return this.lowerReturnStatement(node);
    case "IfStatement":
      return this.lowerIfStatement(node);
    case "WhileStatement":
      return this.lowerWhileStatement(node);
    case "ForStatement":
      return this.lowerForStatement(node);
    case "ForOfStatement":
      return this.lowerForOfStatement(node);
    case "ForInStatement":
      return this.lowerForInStatement(node);
    case "DoWhileStatement":
      return this.lowerDoWhileStatement(node);
    case "BreakStatement":
      return this.builder.break();
    case "ContinueStatement":
      return this.builder.continue();
    case "TryStatement":
      return this.lowerTryStatement(node);
    case "ThrowStatement":
      return this.lowerThrowStatement(node);
    case "SwitchStatement":
      return this.lowerSwitchStatement(node);
    default:
      throw new Error(`Unsupported statement: ${node.type}`);
    }
  }

  lowerVariableDeclaration(node) {
    const declarations = (node.declarations || []).map(decl => this.lowerVariableDeclarator(decl));
    return this.builder.variableDeclaration(declarations, { kind: node.kind });
  }

  lowerVariableDeclarator(node) {
    let idNode;
    let isPattern = false;

    if (node.id.type === "Identifier") {
      this.addBinding(node.id.name);
      idNode = this.lowerExpression(node.id);
    } else if (node.id.type === "ArrayPattern") {
      idNode = this.lowerArrayPattern(node.id);
      isPattern = true;
    } else if (node.id.type === "ObjectPattern") {
      idNode = this.lowerObjectPattern(node.id);
      isPattern = true;
    } else {
      throw new Error(`Unsupported declarator id: ${node.id.type}`);
    }

    const initRef = node.init ? this.lowerExpression(node.init) : null;

    // For patterns, pass the pattern object itself, not just a name
    if (isPattern) {
      return this.builder.varDecl(idNode, initRef);
    }

