    "BinaryExpression",
    "LogicalExpression",
    "AssignmentExpression",
    "UpdateExpression",
    "ConditionalExpression",
    "UnaryExpression",
    "CallExpression",
    "MemberExpression",
    "NewExpression",
    "ArrayExpression",
    "ObjectExpression",
    "Property",
    "BlockStatement",
    "IfStatement",
    "SwitchStatement",
    "SwitchCase",
    "WhileStatement",
    "DoWhileStatement",
    "ForStatement",
    "ForOfStatement",
    "ForInStatement",
    "ReturnStatement",
    "BreakStatement",
    "ContinueStatement",
    "ExpressionStatement",
    "Program",
    "FunctionDeclaration",
    "VariableDeclaration",
    "VariableDeclarator",
    "TryStatement",
    "CatchClause",
    "ThrowStatement",
    "AwaitExpression"
