        tokens.push({ type: "PUNCT", value: char });
        this.advance();
      } else if (/[+\-*/%&|^<>=!?:]/.test(char)) {
        tokens.push({ type: "OPERATOR", value: char });
        this.advance();
      } else {
        this.advance();
      }
    }
    return tokens;
  }

