      while (pos < line.length) {
        let matched = false;

        for (const { type, pattern } of tokenPatterns) {
          const regex = new RegExp(`^${pattern.source}`, "i");
          const match = line.slice(pos).match(regex);

          if (match) {
            if (type !== "WHITESPACE" && type !== "COMMENT") {
              tokens.push({
                type,
                value: match[0],
                position: pos,
              });
            }
            pos += match[0].length;
            matched = true;
            break;
          }
        }

        if (!matched) {
          pos++;
        }
