        code: targetCode,
        sourceLanguage,
        targetLanguage,
        duration: Date.now() - startTime,
        type: "full-translation",
        metrics: {
          inputSize: sourceCode.length,
          outputSize: targetCode.length,
          compressionRatio: (targetCode.length / sourceCode.length).toFixed(2)
        }
      };
    } catch (error) {
      return {
